20260909b_add_etapa8_indexes.sql:
-- ETAPA 8 (Ross): índices aditivos para queries frecuentes de inventario,
-- ventas, movimientos, solicitudes, auditoría y notificaciones.
-- Migración NO destructiva: solo CREATE INDEX + CREATE INDEX. No toca datos.

-- Inventory: listado y replenish por ubicación (inventario de una tienda/almacén)
CREATE INDEX "Inventory_locationId_idx" ON "Inventory"("locationId");

-- Sale: ventas por usuario; listado por tienda ordenado por fecha descendente
CREATE INDEX "Sale_userId_idx" ON "Sale"("userId");
CREATE INDEX "Sale_locationId_saleDate_idx" ON "Sale"("locationId", "saleDate" DESC);

-- SaleItem: reportes de ventas por producto; pre-check de borrado de producto
CREATE INDEX "SaleItem_productId_idx" ON "SaleItem"("productId");

-- Payment: pagos por venta (FK con onDelete Cascade requiere índice)
CREATE INDEX "Payment_saleId_idx" ON "Payment"("saleId");

-- Return: devoluciones por venta y por producto (reportes)
CREATE INDEX "Return_saleId_idx" ON "Return"("saleId");
CREATE INDEX "Return_productId_idx" ON "Return"("productId");

-- Movement: historial por producto; entradas/ORM de tienda
CREATE INDEX "Movement_productId_idx" ON "Movement"("productId");
CREATE INDEX "Movement_toLocationId_idx" ON "Movement"("toLocationId");

-- ProductRequest: job de reposición (status + expectedDate); listado por tienda;
-- solicitudes de un usuario
CREATE INDEX "ProductRequest_status_expectedDate_idx" ON "ProductRequest"("status", "expectedDate");
CREATE INDEX "ProductRequest_locationId_idx" ON "ProductRequest"("locationId");
CREATE INDEX "ProductRequest_requestedById_idx" ON "ProductRequest"("requestedById");

-- RequestHistory: línea de tiempo por solicitud (FK sin índice)
CREATE INDEX "RequestHistory_requestId_idx" ON "RequestHistory"("requestId");

-- AuditLog: auditoría por usuario; listado ordenado descendente
CREATE INDEX "AuditLog_userId_idx" ON "AuditLog"("userId");
CREATE INDEX "AuditLog_createdAt_idx" ON "AuditLog"("createdAt" DESC);

-- Notification: bandeja por usuario (filtra por leído/no leído)
CREATE INDEX "Notification_userId_read_idx" ON "Notification"("userId", "read");

-- Cost: histórico por producto; por proveedor
CREATE INDEX "Cost_productId_idx" ON "Cost"("productId");
CREATE INDEX "Cost_supplierId_idx" ON "Cost"("supplierId");

-- ProductImporter: productos de un importador (borrado/consulta)
CREATE INDEX "ProductImporter_importerId_idx" ON "ProductImporter"("importerId");

20261103_physical_stock_and_returns.sql:
-- Aditiva. LEGACY conserva saldos y hechos históricos sin inferir recepciones o reintegros.
CREATE TYPE "MovementStatus" AS ENUM ('LEGACY', 'IN_TRANSIT', 'RECEIVED');
CREATE TYPE "ReturnDisposition" AS ENUM ('LEGACY', 'PENDING_INSPECTION', 'SELLABLE', 'NOT_SELLABLE', 'MIXED');
ALTER TABLE "Movement"
  ADD COLUMN "status" "MovementStatus" NOT NULL DEFAULT 'LEGACY',
  ADD COLUMN "receivedQuantity" INTEGER NOT NULL DEFAULT 0,
  ADD COLUMN "receivedAt" TIMESTAMP(3);
ALTER TABLE "Return"
  ADD COLUMN "disposition" "ReturnDisposition" NOT NULL DEFAULT 'LEGACY',
  ADD COLUMN "restockedQuantity" INTEGER NOT NULL DEFAULT 0,
  ADD COLUMN "discardedQuantity" INTEGER NOT NULL DEFAULT 0,
  ADD COLUMN "debtReduction" DECIMAL(65,30) NOT NULL DEFAULT 0,
  ADD COLUMN "refundAmount" DECIMAL(65,30) NOT NULL DEFAULT 0,
  ADD COLUMN "inspectedAt" TIMESTAMP(3);
ALTER TABLE "Movement" ADD CONSTRAINT "Movement_received_quantity_valid" CHECK (
  "status" = 'LEGACY' OR ("quantity" > 0 AND "receivedQuantity" >= 0 AND "receivedQuantity" <= "quantity")
);
ALTER TABLE "Return" ADD CONSTRAINT "Return_inspection_quantities_valid" CHECK (
  "disposition" = 'LEGACY' OR ("quantity" > 0 AND "restockedQuantity" >= 0 AND "discardedQuantity" >= 0
    AND "restockedQuantity" + "discardedQuantity" <= "quantity")
);
ALTER TABLE "Return" ADD CONSTRAINT "Return_financial_allocation_valid" CHECK (
  "disposition" = 'LEGACY' OR ("debtReduction" >= 0 AND "refundAmount" >= 0
    AND "debtReduction" + "refundAmount" = "amount")
);
CREATE INDEX "Movement_status_date_idx" ON "Movement"("status", "date");
CREATE INDEX "Return_disposition_date_idx" ON "Return"("disposition", "date");

20261103b_commercial_controls.sql:
-- Aditiva. No certifica ni completa referencias bancarias o facturas históricas.
CREATE TYPE "SaleStatus" AS ENUM ('CONFIRMED', 'VOIDED');
ALTER TABLE "Sale" ADD COLUMN "status" "SaleStatus" NOT NULL DEFAULT 'CONFIRMED',
 ADD COLUMN "voidReason" TEXT, ADD COLUMN "voidedAt" TIMESTAMP(3), ADD COLUMN "voidedById" INTEGER;
CREATE TABLE "ReceivingAccount" (
 "id" SERIAL NOT NULL PRIMARY KEY, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true
);
CREATE UNIQUE INDEX "ReceivingAccount_code_key" ON "ReceivingAccount"("code");
ALTER TABLE "Payment" ADD COLUMN "receivingAccountId" INTEGER, ADD COLUMN "bankReference" TEXT,
 ADD COLUMN "bankOperationDate" TEXT, ADD COLUMN "verifiedAt" TIMESTAMP(3), ADD COLUMN "verifiedById" INTEGER;
ALTER TABLE "Payment" ADD CONSTRAINT "Payment_receivingAccountId_fkey" FOREIGN KEY ("receivingAccountId") REFERENCES "ReceivingAccount"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Payment" ADD CONSTRAINT "Payment_verifiedById_fkey" FOREIGN KEY ("verifiedById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE UNIQUE INDEX "Payment_receivingAccountId_bankReference_bankOperationDate_key" ON "Payment"("receivingAccountId", "bankReference", "bankOperationDate");
CREATE TABLE "PurchaseInvoice" (
 "id" SERIAL NOT NULL PRIMARY KEY, "supplierId" INTEGER NOT NULL, "documentIdentity" TEXT NOT NULL,
 "identityKey" TEXT NOT NULL, "contentHash" TEXT NOT NULL, "result" JSONB NOT NULL,
 "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CONSTRAINT "PurchaseInvoice_supplierId_fkey" FOREIGN KEY ("supplierId") REFERENCES "Supplier"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE UNIQUE INDEX "PurchaseInvoice_supplierId_identityKey_key" ON "PurchaseInvoice"("supplierId", "identityKey");
ALTER TABLE "Cost" ADD COLUMN "purchaseInvoiceId" INTEGER;
ALTER TABLE "Cost" ADD CONSTRAINT "Cost_purchaseInvoiceId_fkey" FOREIGN KEY ("purchaseInvoiceId") REFERENCES "PurchaseInvoice"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Sale" ADD CONSTRAINT "Sale_void_metadata_valid" CHECK (
 "status" <> 'VOIDED' OR ("voidedAt" IS NOT NULL AND "voidedById" IS NOT NULL AND length(trim("voidReason")) >= 10)
);
